import AppKit
import CryptoKit
import PocketCore
import SwiftUI

/// Watches the system pasteboard, owns the history, and persists it.
@MainActor
final class ClipStore: ObservableObject {
    static let historyLimit = 200
    private static let maxTextLength = 500_000
    private static let maxImageBytes = 25_000_000
    private static let privatePasteboardTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ]

    @Published private(set) var items: [ClipItem] = []
    @Published private(set) var toast: String?

    private let pasteboard = NSPasteboard.general
    private let directory: URL
    private var lastChangeCount: Int
    private var timer: Timer?
    private var toastTask: Task<Void, Never>?
    private let thumbnails = NSCache<NSString, NSImage>()

    init() {
        let support = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        directory = support.appendingPathComponent("Pocket", isDirectory: true)
        lastChangeCount = pasteboard.changeCount
        do {
            try FileManager.default.createDirectory(
                at: directory.appendingPathComponent("images"), withIntermediateDirectories: true
            )
        } catch {
            NSLog("Pocket: could not create storage directory: \(error.localizedDescription)")
        }
        items = load()
    }

    // MARK: Lifecycle

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
    }

    // MARK: Queries

    func results(query: String, filter: ClipFilter) -> [ClipItem] {
        let needle = query.trimmingCharacters(in: .whitespacesAndNewlines)
        return items.filter { item in
            guard filter.matches(item) else { return false }
            guard !needle.isEmpty else { return true }
            let haystack = [item.text, item.sourceApp, item.kind.rawValue].compactMap { $0 }.joined(separator: " ")
            return haystack.localizedCaseInsensitiveContains(needle)
        }
    }

    func count(for filter: ClipFilter) -> Int {
        items.filter(filter.matches).count
    }

    var dailyCounts: [Int] { History.dailyCounts(items) }

    func image(for item: ClipItem) -> NSImage? {
        guard let file = item.imageFile else { return nil }
        if let cached = thumbnails.object(forKey: file as NSString) { return cached }
        guard let image = NSImage(contentsOf: imageURL(file)) else { return nil }
        thumbnails.setObject(image, forKey: file as NSString)
        return image
    }

    // MARK: Actions

    func copy(_ item: ClipItem) {
        pasteboard.clearContents()
        switch item.kind {
        case .image:
            guard let image = image(for: item) else { return flash("Image file is missing") }
            pasteboard.writeObjects([image])
        default:
            pasteboard.setString(item.text ?? "", forType: .string)
        }
        lastChangeCount = pasteboard.changeCount
        commit(History.inserting(item.touched(at: Date()), into: items, limit: Self.historyLimit))
        flash("Copied")
    }

    func apply(_ transform: TextTransform, to item: ClipItem) {
        guard let text = item.text, let result = transform.apply(to: text) else {
            NSSound.beep()
            return flash("Can't \(transform.title.lowercased()) this")
        }
        pasteboard.clearContents()
        pasteboard.setString(result, forType: .string)
        lastChangeCount = pasteboard.changeCount
        let clip = ClipItem.text(result, source: "Pocket")
        commit(History.inserting(clip, into: items, limit: Self.historyLimit))
        flash("\(transform.title) — copied")
    }

    func togglePin(_ item: ClipItem) {
        items = items.map { $0.id == item.id ? $0.pinned(!$0.isPinned) : $0 }
        save()
    }

    func delete(_ item: ClipItem) {
        items = items.filter { $0.id != item.id }
        removeFiles(for: [item])
        save()
    }

    func clearUnpinned() {
        let removed = items.filter { !$0.isPinned }
        items = items.filter(\.isPinned)
        removeFiles(for: removed)
        save()
        flash("Cleared \(removed.count) clips")
    }

    func flash(_ message: String) {
        toast = message
        toastTask?.cancel()
        toastTask = Task { [weak self] in
            try? await Task.sleep(for: .seconds(1.6))
            guard !Task.isCancelled else { return }
            self?.toast = nil
        }
    }

    // MARK: Capture

    private func poll() {
        guard pasteboard.changeCount != lastChangeCount else { return }
        lastChangeCount = pasteboard.changeCount
        capture()
    }

    private func capture() {
        let types = pasteboard.types ?? []
        guard !types.contains(where: { Self.privatePasteboardTypes.contains($0.rawValue) }) else { return }
        let source = NSWorkspace.shared.frontmostApplication?.localizedName

        if let text = pasteboard.string(forType: .string),
           !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            guard text.count <= Self.maxTextLength else { return }
            commit(History.inserting(.text(text, source: source), into: items, limit: Self.historyLimit))
        } else if let clip = captureImage(source: source) {
            commit(History.inserting(clip, into: items, limit: Self.historyLimit))
        }
    }

    private func captureImage(source: String?) -> ClipItem? {
        guard let raw = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff),
              raw.count <= Self.maxImageBytes,
              let rep = NSBitmapImageRep(data: raw),
              let png = rep.representation(using: .png, properties: [:])
        else { return nil }

        let hash = SHA256.hash(data: png).map { String(format: "%02x", $0) }.joined()
        if let existing = items.first(where: { $0.fingerprint == "i:" + hash }) {
            return existing.touched(at: Date())
        }

        let file = "\(UUID().uuidString).png"
        do {
            try png.write(to: imageURL(file), options: .atomic)
        } catch {
            NSLog("Pocket: could not save image: \(error.localizedDescription)")
            return nil
        }
        return .image(file: file, hash: hash, width: rep.pixelsWide, height: rep.pixelsHigh, source: source)
    }

    // MARK: Persistence

    private func commit(_ result: (items: [ClipItem], evicted: [ClipItem])) {
        items = result.items
        removeFiles(for: result.evicted)
        save()
    }

    private var storeURL: URL { directory.appendingPathComponent("history.json") }

    private func imageURL(_ file: String) -> URL {
        directory.appendingPathComponent("images").appendingPathComponent(file)
    }

    private func load() -> [ClipItem] {
        guard FileManager.default.fileExists(atPath: storeURL.path) else { return [] }
        do {
            return try JSONDecoder().decode([ClipItem].self, from: Data(contentsOf: storeURL))
        } catch {
            NSLog("Pocket: could not read history: \(error.localizedDescription)")
            return []
        }
    }

    private func save() {
        do {
            try JSONEncoder().encode(items).write(to: storeURL, options: .atomic)
        } catch {
            NSLog("Pocket: could not save history: \(error.localizedDescription)")
        }
    }

    private func removeFiles(for removed: [ClipItem]) {
        let stillUsed = Set(items.compactMap(\.imageFile))
        for file in removed.compactMap(\.imageFile) where !stillUsed.contains(file) {
            thumbnails.removeObject(forKey: file as NSString)
            try? FileManager.default.removeItem(at: imageURL(file))
        }
    }
}
